CREATE TABLE public.drugs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  name text NOT NULL,
  brand text,
  drug_class text NOT NULL,
  indication text NOT NULL,
  route text NOT NULL,
  absorption_site text NOT NULL,
  target_organ text NOT NULL,
  receptors text[] NOT NULL DEFAULT '{}',
  mechanism text NOT NULL,
  metabolism_organ text NOT NULL,
  metabolism_enzymes text[] NOT NULL DEFAULT '{}',
  elimination text NOT NULL,
  half_life_hours numeric NOT NULL,
  onset_minutes integer NOT NULL,
  peak_minutes integer NOT NULL,
  typical_dose text NOT NULL,
  clinical_notes text[] NOT NULL DEFAULT '{}',
  source_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.drugs TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.drugs TO authenticated;
GRANT ALL ON public.drugs TO service_role;

ALTER TABLE public.drugs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Drugs are publicly readable"
  ON public.drugs FOR SELECT
  USING (true);

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$ LANGUAGE plpgsql SET search_path = public;

CREATE TRIGGER update_drugs_updated_at
  BEFORE UPDATE ON public.drugs
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

